  first row.
* Groups and DISTINCT treat 1 and 1.0 as equal (numbers compare
  numerically) but keep TRUE distinct from 1.
* ``LIMIT``/``OFFSET`` must not be negative.
"""

import csv
import decimal
import functools
import os
import re

from . import nodes
from .errors import QueryError

__all__ = ["Result", "execute"]


class Result:
    """The result of a query: ``columns`` (list of str), ``rows`` (list of
    tuples)."""

    def __init__(self, columns, rows):
        self.columns = list(columns)
        self.rows = list(rows)

    def __repr__(self):
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)

    def __eq__(self, other):
        if not isinstance(other, Result):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows

    def __len__(self):
        return len(self.rows)

    def __iter__(self):
        return iter(self.rows)


# ---------------------------------------------------------------------------
# Tables

_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


def _convert(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _FLOAT_RE.fullmatch(field):
        return float(field)
    return field


class _Table:
    def __init__(self, header, rows):
        self.header = header
        self.rows = rows
        self._index = {}
        for i, name in enumerate(header):
            self._index.setdefault(name.lower(), []).append(i)

    def resolve(self, name):
        """Return the index of column ``name`` (case-insensitive)."""
        found = self._index.get(name.lower())
        if not found:
            raise QueryError("unknown column: %s" % name)
        if len(found) > 1:
            raise QueryError("ambiguous column: %s" % name)
        return found[0]


def _read_table(directory, name):
    path = os.path.join(directory, name + ".csv")
    if not os.path.isfile(path):
        raise QueryError("unknown table: %s" % name)
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                raise QueryError("table %s has no header line" % name)
            width = len(header)
            rows = []
            for record in reader:
                if not record:
                    continue
                if len(record) > width:
                    raise QueryError(
                        "table %s, line %d: %d fields but the header has %d"
                        % (name, reader.line_num, len(record), width)
                    )
                values = [_convert(v) for v in record]
                values.extend([None] * (width - len(values)))
                rows.append(tuple(values))
    except QueryError:
        raise
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError("cannot read table %s: %s" % (name, e))
    return _Table(header, rows)


# ---------------------------------------------------------------------------
# Values

_AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}
_SCALARS = {
    # name: (min args, max args or None)
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}


def _is_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _kind(v):
    if isinstance(v, bool):
        return "boolean"
    if _is_number(v):
        return "number"
    if isinstance(v, str):
        return "string"
    return type(v).__name__


def _describe(v):
    if v is True:
        return "TRUE"
    if v is False:
        return "FALSE"
    if isinstance(v, str):
        return "'%s'" % v.replace("'", "''")
    return repr(v)


def _compare(a, b):
    """Compare two non-NULL values: -1, 0 or 1. Raises on mixed types."""
    ka, kb = _kind(a), _kind(b)
    if ka != kb:
        raise QueryError(
            "cannot compare %s %s with %s %s" % (ka, _describe(a), kb, _describe(b))
        )
    if a < b:
        return -1
    if a > b:
        return 1
    return 0


def _key(v):
    """A hashable key that equates values that compare equal (1 and 1.0)
    but keeps booleans distinct from numbers."""
    if v is None:
        return (0,)
    if isinstance(v, bool):
        return (1, v)
    if _is_number(v):
        return (2, v)
    return (3, v)


def _text(v):
    if v is True:
        return "true"
    if v is False:
        return "false"
    return str(v)


def _check_bool(v, what):
    if v is not None and not isinstance(v, bool):
        raise QueryError("%s needs a boolean, got %s" % (what, _describe(v)))
    return v


def _and(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _or(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def _not(a):
    return None if a is None else not a


_like_cache = {}


def _like_regex(pattern):
    rx = _like_cache.get(pattern)
    if rx is None:
        parts = []
        for ch in pattern:
            if ch == "%":
                parts.append(".*")
            elif ch == "_":
                parts.append(".")
            else:
                parts.append(re.escape(ch))
        rx = re.compile("".join(parts), re.DOTALL)
        _like_cache[pattern] = rx
    return rx


def _round(x, n=None):
    if not _is_number(x):
        raise QueryError("ROUND needs a number, got %s" % _describe(x))
    if n is not None and (not isinstance(n, int) or isinstance(n, bool)):
        raise QueryError("ROUND needs an integer number of places, got %s" % _describe(n))
    d = decimal.Decimal(repr(x)) if isinstance(x, float) else decimal.Decimal(x)
    if not d.is_finite():
        if n is None:
            raise QueryError("cannot round %s to an integer" % _describe(x))
        return x
    exp = decimal.Decimal(1).scaleb(-(n or 0))
    ctx = decimal.Context(prec=10000, rounding=decimal.ROUND_HALF_UP)
    try:
        q = d.quantize(exp, context=ctx)
    except decimal.InvalidOperation:
        q = d
    if n is None:
        return int(q)
    return float(q)


def _arith(op, a, b):
    if a is None or b is None:
        return None
    if not _is_number(a) or not _is_number(b):
        raise QueryError(
            "cannot apply %s to %s and %s" % (op, _describe(a), _describe(b))
        )
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    # "/"
    if b == 0:
        return None
    try:
        return a / b
    except OverflowError:
        raise QueryError("numeric overflow in %s / %s" % (_describe(a), _describe(b)))


_COMPARISONS = {
    "=": lambda c: c == 0,
    "!=": lambda c: c != 0,
    "<>": lambda c: c != 0,
    "<": lambda c: c < 0,
    "<=": lambda c: c <= 0,
    ">": lambda c: c > 0,
    ">=": lambda c: c >= 0,
}


def _children(expr):
    if isinstance(expr, nodes.Unary):
        return [expr.operand]
    if isinstance(expr, nodes.Binary):
        return [expr.left, expr.right]
    if isinstance(expr, nodes.IsNull):
        return [expr.expr]
    if isinstance(expr, nodes.InList):
        return [expr.expr] + list(expr.items)
    if isinstance(expr, nodes.Between):
        return [expr.expr, expr.low, expr.high]
    if isinstance(expr, nodes.Like):
        return [expr.expr, expr.pattern]
    if isinstance(expr, nodes.FuncCall):
        return list(expr.args)
    return []


def _is_aggregate(expr):
    return isinstance(expr, nodes.FuncCall) and expr.name.upper() in _AGGREGATES


def _has_aggregate(expr):
    if expr is None:
        return False
    if _is_aggregate(expr):
        return True
    return any(_has_aggregate(c) for c in _children(expr))


# ---------------------------------------------------------------------------
# Evaluation


class _Evaluator:
    def __init__(self, table):
        self.table = table

    # -- static checks ---------------------------------------------------

    def check(self, expr, where, allow_agg, in_agg=False):
        """Check columns, functions, arity and aggregate placement."""
        if isinstance(expr, nodes.Literal):
            return
        if isinstance(expr, nodes.Column):
            self.table.resolve(expr.name)
            return
        if isinstance(expr, nodes.FuncCall):
            name = expr.name.upper()
            if name in _AGGREGATES:
                if not allow_agg:
                    raise QueryError("aggregate %s is not allowed in %s" % (name, where))
                if in_agg:
                    raise QueryError("aggregates can't be nested: %s" % expr.text)
                if expr.star:
                    if name != "COUNT" or expr.args:
                        raise QueryError("only COUNT accepts *")
                elif len(expr.args) != 1:
                    raise QueryError(
                        "%s takes exactly 1 argument, got %d" % (name, len(expr.args))
                    )
                for a in expr.args:
                    self.check(a, where, allow_agg, True)
                return
            if name not in _SCALARS:
                raise QueryError("unknown function: %s" % expr.name)
            if expr.star:
                raise QueryError("%s does not accept *" % name)
            lo, hi = _SCALARS[name]
            n = len(expr.args)
            if n < lo or (hi is not None and n > hi):
                if lo == hi:
                    want = "%d argument%s" % (lo, "" if lo == 1 else "s")
                elif hi is None:
                    want = "at least %d argument%s" % (lo, "" if lo == 1 else "s")
                else:
                    want = "%d to %d arguments" % (lo, hi)
                raise QueryError("%s takes %s, got %d" % (name, want, n))
            for a in expr.args:
                self.check(a, where, allow_agg, in_agg)
            return
        if isinstance(
            expr,
            (nodes.Unary, nodes.Binary, nodes.IsNull, nodes.InList, nodes.Between, nodes.Like),
        ):
            for c in _children(expr):
                self.check(c, where, allow_agg, in_agg)
            return
        raise QueryError("unsupported expression: %r" % (expr,))

    @staticmethod
    def check_grouped(expr, group_by):
        """Every column outside an aggregate must lie within a GROUP BY
        expression."""
        if any(expr == g for g in group_by):
            return
        if _is_aggregate(expr):
            return
        if isinstance(expr, nodes.Column):
            raise QueryError(
                "column %s must appear in GROUP BY or be used in an aggregate"
                % (expr.text or expr.name)
            )
        for c in _children(expr):
            _Evaluator.check_grouped(c, group_by)

    # -- evaluation ------------------------------------------------------

    def eval(self, expr, row, group=None):
        """Evaluate ``expr`` on ``row``; ``group`` is the list of rows for
        aggregates (None when the query is not grouped)."""
        ev = self.eval
        if isinstance(expr, nodes.Literal):
            return expr.value
        if isinstance(expr, nodes.Column):
            return row[self.table.resolve(expr.name)]
        if isinstance(expr, nodes.Binary):
            op = expr.op.upper()
            a = ev(expr.left, row, group)
            b = ev(expr.right, row, group)
            if op == "AND":
                return _and(_check_bool(a, "AND"), _check_bool(b, "AND"))
            if op == "OR":
                return _or(_check_bool(a, "OR"), _check_bool(b, "OR"))
            if op in _COMPARISONS:
                if a is None or b is None:
                    return None
                return _COMPARISONS[op](_compare(a, b))
            if op == "||":
                if a is None or b is None:
                    return None
                return _text(a) + _text(b)
            if op in ("+", "-", "*", "/"):
                return _arith(op, a, b)
            raise QueryError("unknown operator: %s" % expr.op)
        if isinstance(expr, nodes.Unary):
            op = expr.op.upper()
            v = ev(expr.operand, row, group)
            if op == "NOT":
                return _not(_check_bool(v, "NOT"))
            if op == "-":
                if v is None:
                    return None
                if not _is_number(v):
                    raise QueryError("cannot negate %s" % _describe(v))
                return -v
            raise QueryError("unknown operator: %s" % expr.op)
        if isinstance(expr, nodes.IsNull):
            v = ev(expr.expr, row, group)
            return (v is not None) if expr.negated else (v is None)
        if isinstance(expr, nodes.InList):
            x = ev(expr.expr, row, group)
            items = [ev(i, row, group) for i in expr.items]
            if x is None:
                result = None
            else:
                result = False
                for item in items:
                    if item is None:
                        result = None
                    elif _compare(x, item) == 0:
                        result = True
                        break
            return _not(result) if expr.negated else result
        if isinstance(expr, nodes.Between):
            x = ev(expr.expr, row, group)
            lo = ev(expr.low, row, group)
            hi = ev(expr.high, row, group)
            ge = None if x is None or lo is None else _compare(lo, x) <= 0
            le = None if x is None or hi is None else _compare(x, hi) <= 0
            result = _and(ge, le)
            return _not(result) if expr.negated else result
        if isinstance(expr, nodes.Like):
            s = ev(expr.expr, row, group)
            p = ev(expr.pattern, row, group)
            for v in (s, p):
                if v is not None and not isinstance(v, str):
                    raise QueryError("LIKE needs strings, got %s" % _describe(v))
            if s is None or p is None:
                return None
            result = _like_regex(p).fullmatch(s) is not None
            return not result if expr.negated else result
        if isinstance(expr, nodes.FuncCall):
            name = expr.name.upper()
            if name in _AGGREGATES:
                return self.aggregate(name, expr, group)
            return self.scalar(name, expr, row, group)
        raise QueryError("unsupported expression: %r" % (expr,))

    def scalar(self, name, expr, row, group):
        if name == "COALESCE":
            for a in expr.args:
                v = self.eval(a, row, group)
                if v is not None:
                    return v
            return None
        args = [self.eval(a, row, group) for a in expr.args]
        if any(a is None for a in args):
            return None
        x = args[0]
        if name in ("LOWER", "UPPER", "LENGTH"):
            if not isinstance(x, str):
                raise QueryError("%s needs a string, got %s" % (name, _describe(x)))
            if name == "LOWER":
                return x.lower()
            if name == "UPPER":
                return x.upper()
            return len(x)
        if name == "ABS":
            if not _is_number(x):
                raise QueryError("ABS needs a number, got %s" % _describe(x))
            return abs(x)
        if name == "ROUND":
            return _round(*args)
        raise QueryError("unknown function: %s" % expr.name)

    def aggregate(self, name, expr, group):
        if group is None:  # pragma: no cover - prevented by grouping logic
            raise QueryError("aggregate %s used outside a grouped query" % name)
        if expr.star:
            return len(group)
        arg = expr.args[0]
        values = [v for v in (self.eval(arg, r) for r in group) if v is not None]
        if name == "COUNT":
            return len(values)
        if not values:
            return None
        if name in ("SUM", "AVG"):
            total = 0
            for v in values:
                if not _is_number(v):
                    raise QueryError("%s needs numbers, got %s" % (name, _describe(v)))
                total += v
            if name == "AVG":
                return total / len(values)
            return total
        best = values[0]
        for v in values[1:]:
            c = _compare(v, best)
            if (name == "MIN" and c < 0) or (name == "MAX" and c > 0):
                best = v
        return best

    def condition(self, expr, row, group, clause):
        v = self.eval(expr, row, group)
        if v is not None and not isinstance(v, bool):
            raise QueryError("%s condition must be boolean, got %s" % (clause, _describe(v)))
        return v is True


# ---------------------------------------------------------------------------
# Sorting


def _sort_cmp(desc_flags):
    def cmp(a, b):
        for x, y, desc in zip(a[1], b[1], desc_flags):
            if x is None and y is None:
                continue
            if x is None:
                return 1 if desc else -1
            if y is None:
                return -1 if desc else 1
            c = _compare(x, y)
            if c:
                return -c if desc else c
        return 0

    return cmp


# ---------------------------------------------------------------------------
# Entry point


def execute(select, directory):
    """Run the query ``select`` (a ``nodes.Select``) against the CSV files in
    ``directory`` and return a ``Result``."""
    table = _read_table(directory, select.table)
    ev = _Evaluator(table)
    group_by = list(select.group_by or [])

    # Output columns.
    if select.columns is None:
        items = [nodes.SelectItem(nodes.Column(h, h)) for h in table.header]
        names = list(table.header)
    else:
        items = list(select.columns)
        names = []
        for item in items:
            if item.alias is not None:
                names.append(item.alias)
            elif isinstance(item.expr, nodes.Column):
                names.append(table.header[table.resolve(item.expr.name)])
            else:
                names.append(item.expr.text)

    # Resolve ORDER BY items: ("out", index) or ("expr", expr).
    order = []
    lowered = [n.lower() for n in names]
    for oi in select.order_by or []:
        e = oi.expr
        if isinstance(e, nodes.Column) and e.name.lower() in lowered:
            order.append(("out", lowered.index(e.name.lower())))
        elif (
            isinstance(e, nodes.Literal)
            and isinstance(e.value, int)
            and not isinstance(e.value, bool)
        ):
            if not 1 <= e.value <= len(names):
                raise QueryError(
                    "ORDER BY position %d is out of range (1 to %d)" % (e.value, len(names))
                )
            order.append(("out", e.value - 1))
        else:
            order.append(("expr", e))

    # Static checks.
    if select.where is not None:
        ev.check(select.where, "WHERE", allow_agg=False)
    for g in group_by:
        ev.check(g, "GROUP BY", allow_agg=False)
    for item in items:
        ev.check(item.expr, "the column list", allow_agg=True)
    if select.having is not None:
        ev.check(select.having, "HAVING", allow_agg=True)
    for kind, e in order:
        if kind == "expr":
            ev.check(e, "ORDER BY", allow_agg=True)

    grouped = (
        bool(group_by)
        or any(_has_aggregate(i.expr) for i in items)
        or _has_aggregate(select.having)
        or any(kind == "expr" and _has_aggregate(e) for kind, e in order)
    )
    if grouped:
        for item in items:
            ev.check_grouped(item.expr, group_by)
        if select.having is not None:
            ev.check_grouped(select.having, group_by)
        for kind, e in order:
            if kind == "expr":
                ev.check_grouped(e, group_by)

    for value, what in ((select.limit, "LIMIT"), (select.offset, "OFFSET")):
        if value is not None and (
            not isinstance(value, int) or isinstance(value, bool) or value < 0
        ):
            raise QueryError("%s must be a non-negative integer" % what)

    # Filter.
    rows = table.rows
    if select.where is not None:
        rows = [r for r in rows if ev.condition(select.where, r, None, "WHERE")]

    # Build (row, group) evaluation contexts.
    if grouped:
        if group_by:
            groups = {}
            for r in rows:
                k = tuple(_key(ev.eval(g, r)) for g in group_by)
                groups.setdefault(k, []).append(r)
            contexts = [(g[0], g) for g in groups.values()]
        else:
            contexts = [(rows[0] if rows else None, rows)]
    else:
        contexts = [(r, None) for r in rows]

    if select.having is not None:
        contexts = [
            (r, g) for r, g in contexts if ev.condition(select.having, r, g, "HAVING")
        ]

    # Project, computing sort keys alongside.
    out = []
    for r, g in contexts:
        values = tuple(ev.eval(item.expr, r, g) for item in items)
        keys = tuple(
            values[x] if kind == "out" else ev.eval(x, r, g) for kind, x in order
        )
        out.append((values, keys))

    if order:
        out.sort(key=functools.cmp_to_key(_sort_cmp([oi.desc for oi in select.order_by])))

    result_rows = [values for values, _ in out]

    if select.distinct:
        seen = set()
        unique = []
        for values in result_rows:
            k = tuple(_key(v) for v in values)
            if k not in seen:
                seen.add(k)
                unique.append(values)
        result_rows = unique

    start = select.offset or 0
    end = None if select.limit is None else start + select.limit
    result_rows = result_rows[start:end]

    return Result(names, result_rows)
